<?php require_once __DIR__.'/includes/auth.php'; if(current_user()) redirect(BASE_URL.'/dashboard.php'); $error=''; if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$s=db()->prepare('SELECT u.*,r.name role_name,s.name service_name FROM users u JOIN roles r ON r.id=u.role_id LEFT JOIN services s ON s.id=u.service_id WHERE u.staff_id=? AND u.status="Active"');$s->execute([trim((string)post('staff_id'))]);$u=$s->fetch(); if($u && password_verify((string)post('password'),$u['password_hash'])){login_user($u);db()->prepare('UPDATE users SET last_login_at=NOW() WHERE id=?')->execute([$u['id']]);audit('LOGIN','users',(int)$u['id'],'Successful login');redirect(BASE_URL.'/dashboard.php');} $error='Invalid staff ID or password.';} ?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Login | CHMS</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="<?=BASE_URL?>/assets/css/style.css" rel="stylesheet"></head><body class="login-page"><div class="login-card"><div class="brand justify-content-center"><div class="brand-icon"><i class="bi bi-heart-pulse"></i></div><div><strong>CHMS</strong><small>Santa Rosa CHO</small></div></div><h2>Staff Sign In</h2><p class="text-muted">Secure access for authorized City Health Office personnel.</p><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><form method="post"><?=csrf_field()?><div class="mb-3"><label>Staff ID</label><input class="form-control" name="staff_id" required autofocus></div><div class="mb-3"><label>Password</label><input type="password" class="form-control" name="password" required></div><button class="btn btn-primary w-100">Sign in</button></form><div class="text-center mt-4"><a href="<?=BASE_URL?>/public/">Public Health Portal</a></div></div></body></html>
